import{_ as r,o as n,c as o,ag as a}from"./chunks/framework.CmaAMB6e.js";const u=JSON.parse('{"title":"Agent 开发学习路径","description":"","frontmatter":{},"headers":[],"relativePath":"agent/learning-path.md","filePath":"agent/learning-path.md","lastUpdated":null}'),e={name:"agent/learning-path.md"};function l(i,t,s,d,g,h){return n(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="agent-开发学习路径" tabindex="-1">Agent 开发学习路径 <a class="header-anchor" href="#agent-开发学习路径" aria-label="Permalink to &quot;Agent 开发学习路径&quot;">​</a></h1><blockquote><p>Agent 专属的概念序列与阶段划分。每个概念自成闭环,不与其他技能绑定。</p><p><strong>定位说明</strong>:使用者是前端工程师,已具备扎实的 Web 工程能力,但对「让 LLM 驱动一个能自主完成任务的程序」缺乏系统认知。本线不重复教编程基础,从「LLM 到底是什么」讲起,直达生产级 Agent 系统。</p><p><strong>语言说明</strong>:主线代码用 Python(Agent 生态最成熟的一侧),但每篇都有「前端对照」小节做 TS/JS 映射。你只需要能读懂 Python 语法,不需要精通它。</p></blockquote><h2 id="学习策略" tabindex="-1">学习策略 <a class="header-anchor" href="#学习策略" aria-label="Permalink to &quot;学习策略&quot;">​</a></h2><ul><li><strong>概念驱动</strong>:按概念顺序推进,每个概念是一篇完整教程</li><li><strong>前端对照</strong>:每篇末尾用小表格把新概念映射回你熟悉的前端知识,降低认知负担</li><li><strong>先跑通再优化</strong>:阶段 1~2 的目标是让 Agent「能跑起来」,阶段 3~4 让它「做得对」,阶段 5 让它「能上线」</li><li><strong>边学边练</strong>:每篇配练习建议,可用 <code>/practice agent &lt;概念&gt;</code> 生成针对性练习</li></ul><h2 id="阶段总览" tabindex="-1">阶段总览 <a class="header-anchor" href="#阶段总览" aria-label="Permalink to &quot;阶段总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>主题</th><th>概念数</th></tr></thead><tbody><tr><td>1</td><td>基础层</td><td>5</td></tr><tr><td>2</td><td>工具能力层</td><td>5</td></tr><tr><td>3</td><td>知识记忆层</td><td>5</td></tr><tr><td>4</td><td>Agent 架构层</td><td>5</td></tr><tr><td>5</td><td>工程化层</td><td>8</td></tr><tr><td>6</td><td>综合实战</td><td>1</td></tr></tbody></table><hr><h2 id="阶段-1-·-基础层" tabindex="-1">阶段 1 · 基础层 <a class="header-anchor" href="#阶段-1-·-基础层" aria-label="Permalink to &quot;阶段 1 · 基础层&quot;">​</a></h2><p>建立正确的心智模型,掌握与模型打交道的基本功。重点是「LLM 不是数据库,也不是搜索引擎」。</p><ul><li><strong>01 LLM 与 Agent 心智模型</strong> - token、上下文窗口、采样参数、Agent 与 ChatBot 的分界、能力边界</li><li><strong>02 Prompt 工程基础</strong> - 角色语义、指令要素、Few-shot、思维链、反模式</li><li><strong>03 结构化输出与 Schema 约束</strong> - JSON Mode、Pydantic Schema、instructor 校验重试、解析兜底</li><li><strong>04 大模型 API 工程实践</strong> - OpenAI/Anthropic SDK、流式、重试退避、限流、多模型 fallback</li><li><strong>05 模型选型与本地部署</strong> - 闭源 vs 开源、能力维度、Ollama、vLLM、模型路由</li></ul><h2 id="阶段-2-·-工具能力层" tabindex="-1">阶段 2 · 工具能力层 <a class="header-anchor" href="#阶段-2-·-工具能力层" aria-label="Permalink to &quot;阶段 2 · 工具能力层&quot;">​</a></h2><p>让 Agent 长出手脚。这是 Agent 区别于 ChatBot 的第一个实质门槛。</p><ul><li><strong>06 Function Calling 机制</strong> - 工具协议本质、tools Schema、tool_choice、并行调用、观察回灌</li><li><strong>07 工具设计与编排</strong> - 工具粒度、描述写法、幂等设计、错误信息自纠、权限分层</li><li><strong>08 代码执行与沙箱</strong> - Docker 隔离、资源限制、e2b 托管沙箱、危险操作黑名单</li><li><strong>09 文件与命令操作</strong> - 工作目录隔离、路径白名单、Shell 危险分级、输出截断、git 撤销</li><li><strong>10 搜索与浏览器能力</strong> - 搜索 API、网页抓取、Playwright、HTML 转 Markdown、成本控制</li></ul><h2 id="阶段-3-·-知识记忆层" tabindex="-1">阶段 3 · 知识记忆层 <a class="header-anchor" href="#阶段-3-·-知识记忆层" aria-label="Permalink to &quot;阶段 3 · 知识记忆层&quot;">​</a></h2><p>解决「模型不知道你的数据」和「对话长了就忘」两个核心问题。</p><ul><li><strong>11 Embedding 与向量检索</strong> - 向量化原理、模型选型、相似度度量、向量库选型、元数据过滤</li><li><strong>12 RAG 基础流水线</strong> - 加载、切分、向量化、存储、检索、拼接、生成;引用溯源</li><li><strong>13 检索质量优化</strong> - 查询改写、HyDE、混合检索、RRF 融合、rerank、父子块检索</li><li><strong>14 记忆系统设计</strong> - 短期/长期记忆、缓冲与摘要、实体记忆、去重、遗忘、持久化</li><li><strong>15 上下文工程与压缩</strong> - lost in the middle、优先级排布、历史压缩、工具输出裁剪、prompt 缓存</li></ul><h2 id="阶段-4-·-agent-架构层" tabindex="-1">阶段 4 · Agent 架构层 <a class="header-anchor" href="#阶段-4-·-agent-架构层" aria-label="Permalink to &quot;阶段 4 · Agent 架构层&quot;">​</a></h2><p>从「能调用工具」到「能自主完成复杂任务」。</p><ul><li><strong>16 ReAct 推理循环</strong> - Thought/Action/Observation、手写循环、死循环检测、双预算熔断</li><li><strong>17 规划与任务分解</strong> - Plan-and-Execute、规划器与执行器分离、依赖图、动态调整</li><li><strong>18 反思与自我修正</strong> - Reflexion、自我批判、外部信号反馈、反思记忆、防空转</li><li><strong>19 Multi-Agent 协作</strong> - supervisor/swarm/流水线、共享状态、LangGraph 实现、代价权衡</li><li><strong>20 状态机与人在回路</strong> - 节点与条件边、中断恢复、检查点持久化、人工审批、澄清追问</li></ul><h2 id="阶段-5-·-工程化层" tabindex="-1">阶段 5 · 工程化层 <a class="header-anchor" href="#阶段-5-·-工程化层" aria-label="Permalink to &quot;阶段 5 · 工程化层&quot;">​</a></h2><p>把 Demo 变成能上线、能运维、能迭代的产品。这一步决定项目生死。</p><ul><li><strong>21 流式输出与前端集成</strong> - SSE、增量协议、工具调用流式、FastAPI、前端增量渲染、取消重连</li><li><strong>22 错误处理与韧性设计</strong> - 错误分类、降级策略、重试幂等、超时部分结果、断路器</li><li><strong>23 评估体系与测试</strong> - 分层评估、评测集、LLM-as-Judge、回归测试、线上反馈闭环</li><li><strong>24 可观测性与成本控制</strong> - Trace/Span、LangSmith/Langfuse、成本归因、慢查询、告警</li><li><strong>25 安全与权限治理</strong> - Prompt Injection、工具防护、最小权限、PII 脱敏、审计、红队</li><li><strong>26 MCP 与生态集成</strong> - MCP 协议、Tools/Resources/Prompts、写 Server、传输方式</li><li><strong>27 长时运行 Agent 与可靠性</strong> - 状态持久化、断点续跑、任务队列、幂等去重、优雅关闭</li><li><strong>28 Agent 产品化与交互设计</strong> - 信任建立、可控感、预期管理、中间态、Copilot 式 vs 自主式</li></ul><h2 id="阶段-6-·-综合实战" tabindex="-1">阶段 6 · 综合实战 <a class="header-anchor" href="#阶段-6-·-综合实战" aria-label="Permalink to &quot;阶段 6 · 综合实战&quot;">​</a></h2><ul><li><strong>29 综合实战项目</strong> - 端到端构建生产级 Agent:架构、工具、RAG、记忆、人审、前端、评估、可观测、安全、部署</li></ul><hr><h2 id="学习建议" tabindex="-1">学习建议 <a class="header-anchor" href="#学习建议" aria-label="Permalink to &quot;学习建议&quot;">​</a></h2><p><strong>如果你是第一次接触 Agent 开发</strong>:严格按顺序学,不要跳。阶段 1 的心智模型会持续影响后面的判断,跳过后很容易把 Agent 当成「高级 ChatBot」来设计。</p><p><strong>如果你已经调过 API、写过 Prompt</strong>:可以快速过阶段 1,但第 03 篇(结构化输出)和第 15 篇(上下文工程)不建议跳——这两篇是区分「能跑」和「稳定跑」的关键。</p><p><strong>如果你只想解决眼前的某个问题</strong>:</p><ul><li>想让 AI 回答基于自己文档的问题 → 11、12、13</li><li>想让 AI 操作你的系统 → 06、07、09、25</li><li>Agent 跑着跑着就失控 → 15、16、20、22</li><li>上线后不知道效果如何 → 23、24</li><li>被注入攻击或担心安全 → 25</li></ul><h2 id="与其他技能线的关系" tabindex="-1">与其他技能线的关系 <a class="header-anchor" href="#与其他技能线的关系" aria-label="Permalink to &quot;与其他技能线的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>技能线</th><th>什么时候需要回头看</th></tr></thead><tbody><tr><td>Python</td><td>主线代码是 Python,若读起来吃力,先看 Python 线 01~05</td></tr><tr><td>前端</td><td>第 21 篇流式渲染、第 28 篇交互设计直接依赖前端功底</td></tr><tr><td>Node.js</td><td>若你想用 TS 而非 Python 实现后端,参考 Node 线的工程实践</td></tr><tr><td>数据库</td><td>第 11 篇的 pgvector、第 14 篇的记忆持久化</td></tr><tr><td>系统设计</td><td>第 22 篇韧性、第 27 篇长时任务的架构视角</td></tr></tbody></table>',32)])])}const p=r(e,[["render",l]]);export{u as __pageData,p as default};
